from django.db import migrations, models
from django.db.models import F


def copy_legacy_fields_to_english(apps, schema_editor):
    db_alias = schema_editor.connection.alias
    website_app = apps.get_app_config("website")

    for model in website_app.get_models():
        field_names = {field.name for field in model._meta.local_fields}

        for field_name in field_names:
            if field_name.endswith("_en"):
                original_field = field_name[:-3]

                if original_field in field_names:
                    model.objects.using(db_alias).update(
                        **{field_name: F(original_field)}
                    )


